const reversePaymentAllocations = `-- name: ReversePaymentAllocations :many
UPDATE payment_allocations SET reversed_at = $1, reversed_reason = $2
WHERE payment_id = $3 AND reversed_at IS NULL
RETURNING charge_id
`

type ReversePaymentAllocationsParams struct {
	Now       *time.Time
	Reason    *string
	PaymentID uuid.UUID
}

// Отмена всех активных распределений платежа; возвращает затронутые начисления.
func (q *Queries) ReversePaymentAllocations(ctx context.Context, arg ReversePaymentAllocationsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, reversePaymentAllocations, arg.Now, arg.Reason, arg.PaymentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var charge_id uuid.UUID
		if err := rows.Scan(&charge_id); err != nil {
			return nil, err
		}
		items = append(items, charge_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

